请对以下 case 进行三维加权评分。

=== case_id ===
Case-27-utility-bill-010

=== 用户原始指令 (query.txt) ===
帮我整个电费卡片,大字写余额叠在图上,点能导航去营业厅,红色提醒欠费

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我整个电费卡片,大字写余额叠在图上,点能导航去营业厅,红色提醒欠费",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "StartNavigate",
        "params": {
          "dstLocation": {
            "latitude": "22.543096",
            "longitude": "114.057865"
          },
          "trafficpe": "Walk"
        }
      }
    }
  ],
  "dataModelSchema": {
    "utility": {
      "balanceCaption": {
        "type": "string",
        "description": "电费余额主数值的短标签",
        "sampleValue": "当前余额"
      },
      "balanceText": {
        "type": "string",
        "description": "电费账户余额展示文本，欠费时可为负数金额",
        "sampleValue": "¥-128.6"
      },
      "accountName": {
        "type": "string",
        "description": "电费账户或户号的脱敏展示名称",
        "sampleValue": "家庭电费账户"
      },
      "statusTitle": {
        "type": "string",
        "description": "电费账户当前告警状态标题",
        "sampleValue": "欠费提醒"
      },
      "statusDetail": {
        "type": "string",
        "description": "欠费处理的短提示",
        "sampleValue": "请及时处理"
      }
    },
    "action": {
      "navigateLabel": {
        "type": "string",
        "description": "前往营业厅导航入口的短按钮文案",
        "sampleValue": "去营业厅"
      }
    },
    "hall": {
      "name": {
        "type": "string",
        "description": "最近营业厅的短名称",
        "sampleValue": "最近营业厅"
      },
      "latitude": {
        "type": "string",
        "description": "最近营业厅位置纬度，用于导航能力参数",
        "sampleValue": "22.543096"
      },
      "longitude": {
        "type": "string",
        "description": "最近营业厅位置经度，用于导航能力参数",
        "sampleValue": "114.057865"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/bolt_fill.svg",
      "description": "闪电实心图标，适合表示电力、电费、用电账户等电力相关服务识别。"
    }
  ]
}

